const lines = stdin.split('\n').map((l) => l.trim()).filter(Boolean);
const micro = [];
const macro = [];
const out = [];

function parse(line) {
  const [head, tail] = line.split(' then ');
  const [type, label] = head.trim().split(/\s+/);
  return { type, label, child: tail ? parse(tail) : null };
}

function run(task) {
  out.push(task.label);
  if (task.child) dispatch(task.child);
}

function dispatch(task) {
  if (task.type === 'sync') run(task);
  else if (task.type === 'micro') micro.push(task);
  else macro.push(task);
}

function drainMicrotasks() {
  while (micro.length) run(micro.shift());
}

lines.map(parse).forEach(dispatch);
drainMicrotasks();
while (macro.length) {
  run(macro.shift());
  drainMicrotasks();
}
console.log(out.join('\n'));

